const execution = $json.execution ?? {};
const workflow = $json.workflow ?? {};
const summary = { workflowId: workflow.id, workflowName: workflow.name, executionId: execution.id, url: execution.url, lastNodeExecuted: execution.lastNodeExecuted, error: execution.error?.message ?? 'Unknown n8n workflow error', failedAt: new Date().toISOString() };
console.error(JSON.stringify(summary));
return { json: summary };
